<?php
namespace App\Console\Commands;use App\Models\ServiceRequest;use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;
class EscalateSlaRequests extends Command{protected $signature='hospitality:escalate-sla';protected $description='Escalate overdue active service requests.';public function handle():int{$count=0;ServiceRequest::withoutGlobalScopes()->whereIn('status',['PENDING','ACCEPTED','ASSIGNED','IN_PROGRESS'])->whereNotNull('completion_due_at')->where('completion_due_at','<',now())->orderBy('id')->chunkById(100,function($rows)use(&$count){foreach($rows as $r){DB::transaction(function()use($r,&$count){$fresh=ServiceRequest::withoutGlobalScopes()->lockForUpdate()->find($r->id);if(!$fresh||!in_array($fresh->status,['PENDING','ACCEPTED','ASSIGNED','IN_PROGRESS'],true)||!$fresh->completion_due_at?->isPast())return;$from=$fresh->status;$fresh->update(['status'=>'ESCALATED']);DB::table('service_request_status_history')->insert(['hotel_id'=>$fresh->hotel_id,'service_request_id'=>$fresh->id,'changed_by'=>null,'from_status'=>$from,'to_status'=>'ESCALATED','note'=>'Automatic SLA escalation','created_at'=>now()]);$count++;});}});$this->info("Escalated {$count} requests.");return self::SUCCESS;}}
